{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "To be eligible for inclusion in the present review, studies needed to meet the following criteria: (i) were children or adolescents aged 5-19 years, all countries and ethnic backgrounds; (ii) had a MetS outcome; (iii) had an adherence to the MedDiet assessed by a validated questionnaire; and (iv) had a longitudinal and cross-­ sectional study design.",
      "reason": "The manuscript specifies the population (children/adolescents 5-19 years), outcome (MetS), exposure (adherence to MedDiet via validated questionnaire), and study design (longitudinal and cross-sectional)."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_20",
      "quote": "we restricted our inclusion criteria to studies published in English.",
      "reason": "The manuscript specifies the language restriction, but does not specify criteria regarding dissemination year or publication status."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not distinguish between exclusion due to outcomes not being measured versus exclusion due to outcome results not being reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_17",
      "quote": "Children and adolescents with low adherence to the MedDiet had greater odds of developing MetS compared to those with medium to high adherence.",
      "reason": "The manuscript specifies the groups used for synthesis (low adherence vs. medium to high adherence) and links them to the review objective of assessing the association between MedDiet adherence and MetS."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PARTIAL",
      "chunk_id": "text_6",
      "quote": "However, to narrow the scope of the meta-­ analysis, only studies that associated the MedDiet with the outcome of MetS were included.",
      "reason": "A rationale is provided for the restriction to MetS outcomes, but no rationale is provided for the restriction to English-language studies."
    }
  ],
  "confidence": 95
}

